(`id`, `name`, `min_expansion`, `max_expansion`, `content_flags`, `content_flags_disabled`)
VALUES
(178300, '360_Tolapumj_Mistletoe_Powder', -1, -1, NULL, NULL)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`);

